import openpyxl, os
wb = openpyxl.load_workbook(os.environ['OUT_XLSX'])
ws = wb['Sheet1']
lookup = {}
for r in range(3, ws.max_row+1):
    i = ws.cell(r,9).value
    j = ws.cell(r,10).value
    k = ws.cell(r,11).value
    if i is not None and j is not None:
        lookup[(i,j)] = k
for r in range(4,7):
    rowkey = ws.cell(r,1).value
    for c in range(3,7):
        colkey = ws.cell(3,c).value
        ws.cell(r,c).value = lookup.get((rowkey,colkey))
wb.save(os.environ['OUT_XLSX'])
wb2 = openpyxl.load_workbook(os.environ['OUT_XLSX'])
ws2 = wb2['Sheet1']
for r in range(3,7):
    print([ws2.cell(r,c).value for c in range(1,7)])
